const allItems = $input.all();

const totalRecords = allItems.length;

const lateCheckIns = allItems.filter(i => i.json.Status === 'Late').length;
const onTimeCount = allItems.filter(i => i.json.Status === 'On Time').length;
// const missingCheckIns = allItems.filter(i => i.json.Status === 'No check-in').length;
// const missingCheckOuts = allItems.filter(i => i.json['Check-Out'] === '-' || !i.json['Check-Out']).length;

const onTimePercentage = totalRecords > 0 
  ? Math.round((onTimeCount / totalRecords) * 100) 
  : 0;

return [{
  json: {
    totalRecords,
    lateCheckIns,
    onTimePercentage,
    data: allItems.map(item => item.json)
  }
}];

// Reference words
const checkInRef = "check in";
const checkOutRef = "check out";
const stepOutRef = "step out";
const stepInRef = "step in";

// Levenshtein similarity function
function similarity(a, b) {
    const m = a.length, n = b.length;
    const dp = Array.from({length: m+1}, () => Array(n+1).fill(0));

    for (let i = 0; i <= m; i++) dp[i][0] = i;
    for (let j = 0; j <= n; j++) dp[0][j] = j;

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            dp[i][j] = Math.min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
            );
        }
    }
    return 1 - dp[m][n] / Math.max(m, n);
}

// Regex for common cases
const checkInRegex = /check[- ]?in|checked[- ]?in|checkin/i;
const checkOutRegex = /check[- ]?out|checked[- ]?out|checkout/i;
const stepOutRegex = /step[- ]?out|stepped[- ]?out|stepout/i;
const stepInRegex = /step[- ]?in|stepped[- ]?in|stepin/i;

// Fuzzy threshold
const threshold = 0.7;

// Process the input dynamically
const results = [];

for (const item of $input.all()) {
    if (!item.json || !item.json.text) continue; // skip if no text

    const originalText = item.json.text;
    const textNormalized = originalText.toLowerCase().replace(/[^a-z ]/g, '');

    if (checkInRegex.test(textNormalized) || similarity(textNormalized, checkInRef) >= threshold) {
        results.push({ ...item, json: { ...item.json, text: "check in" } });
    } else if (checkOutRegex.test(textNormalized) || similarity(textNormalized, checkOutRef) >= threshold) {
        results.push({ ...item, json: { ...item.json, text: "check out" } });
    } else if (stepOutRegex.test(textNormalized) || similarity(textNormalized, stepOutRef) >= threshold) {
        results.push({ ...item, json: { ...item.json, text: "step out" } });
    } else if (stepInRegex.test(textNormalized) || similarity(textNormalized, stepInRef) >= threshold) {
        results.push({ ...item, json: { ...item.json, text: "step in" } });
    }
    // else ignore completely
}

return results;

// List of user IDs you want to track
const trackedUserIds = [
 "U09UERMETJT", // Ammad Afzal
  "U0BE5G6K6TU" // Noman 
];

// Set for quick membership checks
const trackedSet = new Set(trackedUserIds);

// Helper function to convert full datetime to "DD/MM/YYYY, hh:mm AM/PM" format
function convertToAMPMWithDate(dateTimeString) {
  if (!dateTimeString) return null;

  const datePart = dateTimeString.split(',')[0].trim();
  const timePart = dateTimeString.split(',')[1].trim();
  let [hours, minutes, seconds] = timePart.split(':');

  const hour = parseInt(hours);
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const hour12 = hour % 12 || 12;

  return `${datePart}, ${hour12}:${minutes} ${ampm}`;
}

// Get the existing data from Group Messages by User node
const existingRecords = $('Group Messages by User1').all();

// Get user profiles from the previous node
const userProfiles = $input.all();

// Map of user profiles by userId
const userProfileMap = new Map();
for (const profile of userProfiles) {
  userProfileMap.set(profile.json.id, profile.json);
}

// Track which tracked users already have a record
const existingUserIds = new Set();

let result = [];
for (const record of existingRecords) {
  // Skip anyone who isn't in the tracked list
  if (!trackedSet.has(record.json.userId)) continue;

  existingUserIds.add(record.json.userId);

  const userProfile = userProfileMap.get(record.json.userId);
  result.push({
    ...record.json,
    checkInTime: convertToAMPMWithDate(record.json.checkInTime),
    checkOutTime: convertToAMPMWithDate(record.json.checkOutTime),
    userName: userProfile ? (userProfile.real_name || userProfile.name) : "Unknown User",
    userRealName: userProfile ? userProfile.real_name : null,
    userDisplayName: userProfile?.profile?.display_name || null,
    totalWorkingHours: record.json.totalWorkingHours || null,
    totalBreakDuration: record.json.totalBreakDuration || null
  });
}

// Add missing tracked users with Absent status
for (const userId of trackedUserIds) {
  if (!existingUserIds.has(userId)) {
    const userProfile = userProfileMap.get(userId);
    result.push({
      userId: userId,
      userName: userProfile ? (userProfile.real_name || userProfile.name) : "Unknown User",
      userRealName: userProfile ? userProfile.real_name : null,
      userDisplayName: userProfile?.profile?.display_name || null,
      date: new Date().toLocaleDateString('en-GB'),
      windowStart: null,
      windowEnd: null,
      checkInTime: null,
      checkOutTime: null,
      totalMessages: 0,
      status: "Absent",
      totalWorkingHours: null,
      totalBreakDuration: null
    });
  }
}

return result;

const results = [];

// USER SHIFT CONFIG (USER ID BASED) 
const userShifts = {
  "U0BE5G6K6TU": { start: 17, end: 1 }, // Noman
  "U09UERMETJT": { start: 17, end: 1 }, // Ammad Afzal
};

// ================= MAIN LOOP =================
for (const item of $input.all()) {

  const userName = item.json.userName;
  const userId = item.json.userId;
  const date = item.json.date;
  const checkInTime = item.json.checkInTime;
  const checkOutTime = item.json.checkOutTime;
  const totalBreakDuration = item.json.totalBreakDuration;

  let status = 'On Time';

  // ===== TIME PARSER =====
  const parseTime = (str) => {
    if (!str) return null;
    const [datePart, timePart] = str.split(', ');
    const [day, month, year] = datePart.split('/');
    return new Date(`${month}/${day}/${year}, ${timePart}`);
  };

  const toMinutes = (date) => date.getHours() * 60 + date.getMinutes();

  const formatMinutes = (mins) => {
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h}h ${m}m`;
  };

  // ===== SHIFT FORMATTER =====
  const formatShiftHour = (hourDecimal) => {

    const hour = Math.floor(hourDecimal);
    const minutes = (hourDecimal % 1) * 60;

    const dateObj = new Date();
    dateObj.setHours(hour, minutes, 0);

    return dateObj.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // ===== BREAK PARSER =====
  const parseBreak = (str) => {
    if (!str || str === '0h 0m') return 0;
    const match = str.match(/(\d+)h\s*(\d+)m/);
    if (!match) return 0;
    return parseInt(match[1]) * 60 + parseInt(match[2]);
  };

  const shift = userShifts[userId];

  // ===== SHIFT DISPLAY =====
  let shiftDisplay = '-';

  if (shift) {
    shiftDisplay = `${formatShiftHour(shift.start)} - ${formatShiftHour(shift.end)}`;
  }

  // ===== STATUS LOGIC =====
  if (!checkInTime) {

    status = 'Absent';

  } else {

    const checkInDate = parseTime(checkInTime);
    const checkInMinutes = toMinutes(checkInDate);

    // Default fallback shift = 1 PM
    const shiftStartHour = shift ? shift.start : 13;

    const lateThreshold = (shiftStartHour * 60) + 15;

    if (checkInMinutes >= lateThreshold) {
      status = 'Late';
    }
  }

  // ===== BREAK + WORK HOURS =====
  let breakDisplay;
  let workHoursDisplay;

  if (status === 'Absent') {

    breakDisplay = '-';
    workHoursDisplay = '-';

  } else {

    const breakMinutes = parseBreak(totalBreakDuration);

    // ===== BREAK DISPLAY =====
    if (!totalBreakDuration || breakMinutes === 0) {
      breakDisplay = 'No Break';
    } else {
      breakDisplay = totalBreakDuration;
    }

    // ===== WORK HOURS =====
    let totalMinutes = 0;

    if (checkInTime) {

      const checkInDate = parseTime(checkInTime);

      let endTime;

      if (!checkOutTime) {

        endTime = new Date(checkInDate);

        if (shift) {

          if (shift.end > shift.start) {
            // Same day shift
            endTime.setHours(shift.end, 0, 0, 0);
          } else {
            // Overnight shift
            endTime.setDate(endTime.getDate() + 1);
            endTime.setHours(shift.end, 0, 0, 0);
          }

        } else {
          // fallback shift
          endTime.setHours(22, 0, 0, 0);
        }

      } else {

        endTime = parseTime(checkOutTime);

        // Handle next-day checkout
        if (endTime < checkInDate) {
          endTime.setDate(endTime.getDate() + 1);
        }
      }

      totalMinutes = Math.floor((endTime - checkInDate) / 60000);

      // 🔥 SUBTRACT BREAK
      totalMinutes = Math.max(0, totalMinutes - breakMinutes);

      workHoursDisplay = formatMinutes(totalMinutes);

    } else {
      workHoursDisplay = '0h 0m';
    }
  }

  // ===== FINAL OUTPUT =====
  results.push({
    json: {
      Name: userName,
      "Shift Time": shiftDisplay,
      Date: date,
      "Check-In": checkInTime || '-',
      "Check-Out": checkInTime ? (checkOutTime ? checkOutTime : '(M)') : '-',
      "Work Hours": workHoursDisplay,
      Break: breakDisplay,
      Status: status
    }
  });
}

return results;
